import java.util.*;
interface NotificationChannel{void send(String studentName,String title);}class EmailChannel implements NotificationChannel{public void send(String s,String t){System.out.println("[Email → "+s+"] "+t);}}class SmsChannel implements NotificationChannel{public void send(String s,String t){System.out.println("[SMS → "+s+"] "+t);}}class AppChannel implements NotificationChannel{public void send(String s,String t){System.out.println("[App → "+s+"] "+t);}}
class Student{String name,department;List<NotificationChannel> channels=new ArrayList<>();Student(String n,String d){name=n;department=d;}public void addChannel(NotificationChannel c){channels.add(c);}}
class Notice{String title;Set<String> departments;Notice(String t,Set<String>d){if(t==null||t.trim().isEmpty())throw new IllegalArgumentException("Notice title is required.");if(d==null||d.isEmpty())throw new IllegalArgumentException("At least one target department is required.");title=t;departments=new LinkedHashSet<>(d);}}
class NoticeBoard{private List<Student> students=new ArrayList<>();public void addStudent(Student s){students.add(s);}public void postNotice(Notice n){System.out.println("Notice '"+n.title+"' posted to "+String.join(", ",n.departments)+".");for(Student s:students)if(n.departments.contains(s.department))for(NotificationChannel c:s.channels)c.send(s.name,n.title);}}
public class CampusNoticeBroadcaster{public static void main(String[] args){NoticeBoard b=new NoticeBoard();Student a=new Student("Asha","CSE");a.addChannel(new EmailChannel());a.addChannel(new AppChannel());Student r=new Student("Ravi","ECE");r.addChannel(new SmsChannel());b.addStudent(a);b.addStudent(r);b.postNotice(new Notice("Lab Closed Tomorrow",new LinkedHashSet<>(Arrays.asList("CSE"))));b.postNotice(new Notice("Fee Deadline Extended",new LinkedHashSet<>(Arrays.asList("CSE","ECE"))));try{b.postNotice(new Notice("Sports Day",new LinkedHashSet<>()));}catch(IllegalArgumentException e){System.out.println("Cannot post notice: "+e.getMessage());}}}